  var axe = "<line x1='60' y1='310' x2='620' y2='310' stroke='var(--encre2)' stroke-width='1.5'/><line x1='60' y1='310' x2='60' y2='60' stroke='var(--encre2)' stroke-width='1.5'/>";
  [1950, 1970, 1990, 2010, 2026].forEach(function (a) { axe += "<text x='" + X(a) + "' y='328' text-anchor='middle' class='lbl'>" + a + "</text>"; });
  [50000, 100000, 150000].forEach(function (p) { axe += "<line x1='56' y1='" + Y(p) + "' x2='620' y2='" + Y(p) + "' stroke='var(--encre2)' stroke-dasharray='2 5' opacity='.5'/><text x='52' y='" + (Y(p) + 4) + "' text-anchor='end' class='lbl'>" + (p / 1000) + " k</text>"; });
  axe += "<text x='64' y='52' class='lbl' style='font-weight:500'>habitants du centre historique</text>";
